<include file="Public:header"/><div class="main-content">    <!-- 内容头部 -->    <div class="breadcrumbs" id="breadcrumbs">        <ul class="breadcrumb">            <li>                <i class="ace-icon fa fa-user"></i>                <a href="{pigcms{:U('Sms/sms_index')}">短信群发详细</a>            </li>            <li class="active">短信群发详细列表</li>        </ul>    </div>    <!-- 内容头部 -->    <div class="page-content">        <div class="page-content-area">            <div class="row">                <div class="form-group" style="border:1px solid #c5d0dc;padding:10px;">                    <a class="btn btn-success" href="{pigcms{:U('Sms/index')}">返回短信群发</a>                </div>                <div class="col-xs-12">                <div id="shopList" class="grid-view">                    <table class="table table-striped table-bordered table-hover">						<thead>							<tr>								<th>编号</th>								<th>发送到手机</th>								<th>发送类型</th>								<th>发送时间</th>								<th>发送内容</th>								<th>发送状态</th>							</tr>						</thead>						<tbody>							<if condition="is_array($record_list) && $record_list">								<volist name="record_list" id="vo">									<tr>										<td>{pigcms{$vo.pigcms_id}</td>										<td>{pigcms{$vo.phone}</td>										<td><if condition="$vo['send_type'] eq 1">指定身份发送<else />指定号码发送</if></td>										<td>{pigcms{$vo.time|date="Y-m-d H:i:s",###}</td>										<td>{pigcms{$vo.text}</td>                                        <td><if condition="isset($status[$vo['status']])">{pigcms{$status[$vo['status']]}<else/>{pigcms{$vo.status}</if></td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="8">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="8">列表为空！</td></tr>							</if>						</tbody>					</table>                </div>            </div>        </div>    </div></div></div><include file="Public:footer"/>